from pathlib import Path
import subprocess
r=Path('/workspace/scratch/7542f0d861f1/ocean-imu');o=r.parent/'experiments/round2'
s=(r/'src/util/W3dSimCommon.cpp').read_text()
a='    WaveDataCSVReader reader(filename);\n    reader.for_each_record([&](const Wave_Data_Sample& rec) {'
b='''    const std::string probe = std::getenv("PROBE_SENSOR_CONTROL") ? std::getenv("PROBE_SENSOR_CONTROL") : "baseline";
    if (probe == "no_acc_error") noise_models_.accel_noise.reset();
    if (probe == "no_gyro_error") noise_models_.gyro_noise.reset();
    if (probe == "no_mag_error") noise_models_.mag_noise.reset();
'''+a
assert a in s;s=s.replace(a,b,1)
a='        Vector3f gyr_b(rec.imu.gyro_x, rec.imu.gyro_y, rec.imu.gyro_z);'
b=a+'''
        // Diagnostic counterfactual only: same wave and yaw motion, zero cruise acceleration.
        if (probe == "no_cruise_acceleration" && options_.underway_reference) {
            const auto t = UnderwayReference::at(rec.time);
            const Vector3f ac(static_cast<float>(t.acceleration[0]),static_cast<float>(t.acceleration[1]),static_cast<float>(t.acceleration[2]));
            acc_b -= quat_from_csv(rec.imu) * ac;
        }
'''
s=s.replace(a,b,1)
(o/'W3dControls.cpp').write_text(s)
